def finalidade(rel: str) -> str:
    if rel in FINALIDADE:
        return FINALIDADE[rel]
    melhores = [k for k in FINALIDADE if k.endswith("/") and rel.startswith(k)]
    return FINALIDADE[max(melhores, key=len)] if melhores else "(sem descrição)"


def montar(skill: Path = SKILL) -> tuple[str, list, int]:
    """(texto do ARVORE-SKILL.md, arquivos sem descrição, número de arquivos) da árvore `skill`."""
    arquivos = sorted(p.relative_to(skill).as_posix() for p in skill.rglob("*")
                      if p.is_file() and "__pycache__" not in p.parts)
    linhas = ["# Árvore da skill e finalidade de cada componente", "",
              f"Raiz: `fundacao-ia-multiprojetos/` · {len(arquivos)} arquivos. Pastas com muitos arquivos de "
              "mesma natureza são descritas uma vez. `evals/` fica fora do pacote `.skill` (vai no pacote completo).", "",
              "| Caminho | Finalidade |", "|---|---|"]
    vistos = set()
    sem = []
    for rel in arquivos:
        f = finalidade(rel)
        if f == "(sem descrição)":
            sem.append(rel)
        chave = next((k for k in FINALIDADE if k.endswith("/") and rel.startswith(k)), None)
        if chave and rel not in FINALIDADE:
            if chave in vistos:
                continue
            vistos.add(chave)
            n = sum(1 for a in arquivos if a.startswith(chave))
            linhas.append(f"| `{chave}` ({n} arquivos) | {f} |")
        else:
            linhas.append(f"| `{rel}` | {f} |")
    return "\n".join(linhas) + "\n", sem, len(arquivos)


def conferir(skill: Path = SKILL, saida: Path = SAIDA) -> dict:
    """Só lê: o ARVORE-SKILL.md atual é o que o gerador gravaria (quebras de linha à parte) e não tem
    "(sem descrição)"."""
    texto, sem, n = montar(skill)
    try:
        atual = saida.read_bytes().decode("utf-8").replace("\r\n", "\n")
    except (OSError, UnicodeDecodeError):
        atual = None
    igual = atual == texto
    lacuna = sem or (atual is not None and "(sem descrição)" in atual)
    acao = ("descreva os arquivos sem descrição em FINALIDADE (entrega/gerar_arvore.py) e " if lacuna else "") + (
        "rode python entrega/gerar_arvore.py e faça o commit do ARVORE-SKILL.md")
    return {"ok": igual and not lacuna, "igual_ao_gerado": igual, "sem_descricao": sem, "arquivos": n,
            "arvore": str(saida), "acao": "nenhuma" if igual and not lacuna else acao}


def main(argv: list | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--conferir", action="store_true",
                    help="não grava: código 1 se o ARVORE-SKILL.md difere do que seria gravado ou tem '(sem descrição)'")
    a = ap.parse_args(argv)
    if a.conferir:
        res = conferir()
        print(json.dumps(res, ensure_ascii=False, indent=1))
        return 0 if res["ok"] else 1
    texto, sem, n = montar()
    SAIDA.write_text(texto, encoding="utf-8", newline="\n")
    print(f"{SAIDA} ({n} arquivos; sem descrição: {sem})")
    return 0


if __name__ == "__main__":
    for _s in (sys.stdout, sys.stderr):
        try:
            _s.reconfigure(encoding="utf-8")
        except (AttributeError, ValueError):
            pass
    raise SystemExit(main())
